llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Solifenacin showed 88% absolute oral bioavailability in healthy men after a 10 mg oral dose versus IV, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Vernakalant absolute oral bioavailability was 71 ± 21% in fasted healthy volunteers after 5 mg/kg p.o. versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "SAHA (vorinostat) had 43% absolute oral bioavailability in fasting humans at 200–400 mg, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Praziquantel showed 27.2 ± 5.4% oral bioavailability in patients, above the 20% threshold, supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Lurasidone absolute oral bioavailability is 9–19% in humans and increases with food to about 20%, providing the main contradictory low-F evidence but with a food effect that mitigates the fasted low value.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer human absolute oral bioavailability measurements (solifenacin 88%, vernakalant 58–71%, SAHA 43%, praziquantel 27%) supports F ≥ 20%. The main low-F analogue, lurasidone, is fasted-state and reaches ~20% with food; encainide's mean is above threshold. The acidic physicochemical prior is a concern but is outweighed by the transferable experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "No high-transfer analogue contains a phosphinic acid or is dianionic at physiological pH, so the acidic permeability liability is not directly covered.",
    "Lurasidone's low F may reflect high first-pass metabolism rather than the permeability limitation expected for the query.",
    "Encainide shows wide interindividual variability (7–82%), adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

